291	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
292	// bytecode and source strings contribute; field boundaries are explicit
293	// (length-prefixed) so that different splits never collide. The source is
294	// hashed as a field value, never read from disk, and the name does not
295	// participate.
296	func ArtifactHash(a Artifact) string {
297		h := sha256.New()
298		h.Write([]byte("contractsentinel-artifact-v1\n"))
299		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
300			fmt.Fprintf(h, "%d\n", len(field))
301			h.Write([]byte(field))
302		}
303		sum := h.Sum(nil)
304		return hex.EncodeToString(sum)
305	}
306	
307	// validCheckStatus reports whether status is one of the four recorded check
308	// conclusions.
309	func validCheckStatus(status string) bool {
310		switch status {
311		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
312			return true
313		}
314		return false
315	}
316	
317	// BuildReport evaluates rules against the artifact and invariant values and
318	// imported check records and produces the report to persist. Insufficient
319	// inputs (missing ABI for a rule that requires it, missing bytecode for a
320	// symbolic rule) fail the whole submission and are never recorded as defects.
321	// Imported checks are validated as a whole: unknown rules, duplicate records,
322	// unknown statuses, missing notes, hash or version mismatches, and a rule
323	// receiving both a check record and an invariant boolean all reject the
324	// submission without producing a report.
325	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
326		if artifact.Name == "" {
327			return Report{}, errInvalid("artifact name is required")
328		}
329		hash := ArtifactHash(artifact)
330		seen := make(map[string]bool, len(rules))
331		ruleByID := make(map[string]Rule, len(rules))
332		for _, rule := range rules {
333			if rule.ID == "" {
334				return Report{}, errInvalid("rule id is required")
335			}
336			if rule.Version == "" {
337				return Report{}, errInvalid("rule " + rule.ID + " version is required")
338			}
339			if seen[rule.ID] {
340				return Report{}, errInvalid("duplicate rule id " + rule.ID)
341			}
342			seen[rule.ID] = true
343			ruleByID[rule.ID] = rule
344			if rule.RequiresABI && artifact.ABI == "" {
345				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
346			}
347			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
348				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
349			}
350		}
351		checkByRule := make(map[string]CheckRecord, len(checks))
352		for _, check := range checks {
353			if check.RuleID == "" {
354				return Report{}, errInvalid("check rule id is required")
355			}
356			rule, ok := ruleByID[check.RuleID]
357			if !ok {
358				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
359			}
360			if _, dup := checkByRule[check.RuleID]; dup {
361				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
362			}
363			if check.ArtifactHash != hash {
364				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
365			}
366			if check.Version != rule.Version {
367				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
368			}
369			if !validCheckStatus(check.Status) {
370				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
371			}
372			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
373				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
374			}
375			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
376				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
377			}
378			checkByRule[check.RuleID] = check
379		}
380		report := Report{
381			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
382			Rules:    []ReportRule{},
383			Findings: []ReportFinding{},
384		}
385		for _, rule := range rules {
386			status := StatusUnchecked
387			note := ""
388			if check, ok := checkByRule[rule.ID]; ok {
389				status = check.Status
390				note = check.Note
391			} else {
392				// No imported check: the invariant booleans decide. The verdict
393				// interpretation is shared with the finding-list path in Run.
394				switch checkInvariant(rule, invariants) {
395				case invariantHolds:
396					status = StatusPass
397				case invariantViolated:
398					status = StatusDefect
399				}
400			}
401			report.Rules = append(report.Rules, ReportRule{
402				ID:          rule.ID,
403				Kind:        rule.Kind,
404				Severity:    rule.Severity,
405				Invariant:   rule.Invariant,
406				RequiresABI: rule.RequiresABI,
407				Version:     rule.Version,
408				Status:      status,
409				Note:        note,
410			})
411			if status == StatusDefect {
412				evidence := note
413				if evidence == "" {
414					evidence = invariantEvidence(rule.Invariant)
415				}
416				report.Findings = append(report.Findings, ReportFinding{
417					ArtifactHash: hash,
418					RuleID:       rule.ID,
419					Version:      rule.Version,
420					Severity:     rule.Severity,
421					Invariant:    rule.Invariant,
422					Evidence:     evidence,
423				})
424			}
425		}
426		report.ReportID = ReportID(report)
427		return report, nil
428	}
429	
430	// canonicalReport is the deterministic content a report id is computed from.
431	// The rules and findings are the report's own ReportRule and ReportFinding
432	// values: their stored JSON fields are exactly the content the id binds, so
433	// the id form reuses the one field representation instead of maintaining a
434	// parallel copy that every field change would have to be mirrored into. The
435	// rule note keeps its omitempty behaviour, so a note omitted and a note
436	// written as an empty string hash alike and reports built only from invariant
437	// booleans keep their original ids.
438	type canonicalReport struct {
439		ArtifactHash string          `json:"artifactHash"`
440		Name         string          `json:"name"`
441		Rules        []ReportRule    `json:"rules"`
442		Findings     []ReportFinding `json:"findings"`
443	}
444	
445	// canonicalize renders a report into its order-independent form. The rule and
446	// finding slices are copied before sorting, so computing an id never reorders
447	// the report itself: a saved report keeps the submission order and a loaded
448	// report keeps the archive order.
449	func canonicalize(report Report) canonicalReport {
450		cr := canonicalReport{
451			ArtifactHash: report.Artifact.Hash,
452			Name:         report.Artifact.Name,
453		}
454		cr.Rules = append(cr.Rules, report.Rules...)
455		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
456		cr.Findings = append(cr.Findings, report.Findings...)
457		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
458		return cr
459	}
460	
461	// ReportID returns the content-addressed identifier of a report. The id binds
462	// the artifact hash, name, complete rule definitions, the invariant value
463	// used by each rule (unchecked and explicit pass are distinct), and the
464	// findings. Rule order, invariant key order and unrelated invariant keys do
465	// not influence it.
466	func ReportID(r Report) string {
467		data, err := json.Marshal(canonicalize(r))
468		if err != nil {
469			panic(err) // canonical values are all strings and bools
470		}
471		sum := sha256.Sum256(data)
472		return hex.EncodeToString(sum[:])
473	}
474	
475	// validateReport checks every archive legality condition against r. It is the
476	// single definition of a legal report: the id and artifact hash are 64
477	// lowercase hex characters, the id matches the content, the artifact name is
478	// present, rule ids are present and unique with non-empty versions, statuses
479	// use the five recorded values, tool-missing and timeout notes are
480	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
481	// artifact hash, version, severity, invariant and evidence match the rule.
482	// The same conditions apply to submissions and to stored archives: a
483	// recomputed id never makes an invalid report legal. fail is errInvalid for
484	// submissions and errCorrupt for stored archives.
485	func validateReport(r Report, fail func(string) error) error {
486		if !validReportID(r.ReportID) {
487			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
488		}
489		if r.Artifact.Name == "" {
490			return fail("report " + r.ReportID + " artifact name is required")
491		}
492		if !validReportID(r.Artifact.Hash) {
493			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
494		}
495		if ReportID(r) != r.ReportID {
496			return fail("report content does not match id " + r.ReportID)
497		}
498		seenRule := make(map[string]bool, len(r.Rules))
499		defectByID := make(map[string]ReportRule)
500		for _, rule := range r.Rules {
501			if rule.ID == "" {
502				return fail("report " + r.ReportID + " has a rule with an empty id")
503			}
504			if seenRule[rule.ID] {
505				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
506			}
507			seenRule[rule.ID] = true
508			if rule.Version == "" {
509				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
510			}
511			switch rule.Status {
512			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
513			default:
514				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
515			}
516			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
517				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
518			}
519			if rule.Status == StatusDefect {
520				defectByID[rule.ID] = rule
521			}
522		}
523		seenFinding := make(map[string]bool, len(r.Findings))
524		for _, f := range r.Findings {
525			if f.RuleID == "" {
526				return fail("report " + r.ReportID + " has a finding with an empty rule id")
527			}
528			rule, ok := defectByID[f.RuleID]
529			if !ok {
530				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
531			}
532			if seenFinding[f.RuleID] {
533				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
534			}
535			seenFinding[f.RuleID] = true
536			if f.ArtifactHash != r.Artifact.Hash {
537				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
538			}
539			if f.Version != rule.Version {
540				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
541			}
542			if f.Severity != rule.Severity {
543				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
544			}
545			if f.Invariant != rule.Invariant {
546				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
547			}
548			wantEvidence := rule.Note
549			if wantEvidence == "" {
550				wantEvidence = invariantEvidence(rule.Invariant)
551			}
552			if f.Evidence != wantEvidence {
553				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
554			}
555		}
556		for id := range defectByID {
557			if !seenFinding[id] {
558				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
559			}
560		}
561		return nil
562	}
