574	// firstInvalidUTF8ByteInString returns the first byte that is not valid UTF-8
575	// inside s. A Go string can carry any bytes, including bytes no JSON text may
576	// contain: json.Marshal (and therefore the canonical marshalling inside
577	// ReportID) silently replaces such a byte with U+FFFD instead of failing, so
578	// neither the id/content check nor the archive round trip can see it.
579	func firstInvalidUTF8ByteInString(s string) (byte, bool) {
580		for i := 0; i < len(s); {
581			r, size := utf8.DecodeRuneInString(s[i:])
582			if r == utf8.RuneError && size == 1 {
583				return s[i], true
584			}
585			i += size
586		}
587		return 0, false
588	}
589	
590	// validateSubmittedText is the in-memory counterpart of the JSON character
591	// gates in ParseAuditInput and loadStoredReport. SaveReport accepts a Report
592	// built directly by a Go caller, whose strings never passed through JSON
593	// decoding; encoding/json marshals such a value without an error while
594	// replacing every invalid UTF-8 byte with U+FFFD, and ReportID computes from
595	// the same rewritten canonical form, so the recomputed id and the
596	// rule/finding correspondence would all match an archive whose text no
597	// longer equals what the caller handed over. Every caller-supplied string is
598	// therefore checked on the raw object — reportId, artifact name and hash,
599	// each rule definition field and status note, and each finding binding field
600	// and evidence — independently of which rules produced defects and of
601	// whether the report carries any finding at all. The rejection is an input
602	// error naming the exact field, with the array position of rules and
603	// findings, and it runs before any filesystem operation.
604	func validateSubmittedText(r Report) error {
605		check := func(field, value string) error {
606			if b, bad := firstInvalidUTF8ByteInString(value); bad {
607				return errInvalid(fmt.Sprintf("invalid UTF-8 byte 0x%02x in report field %s", b, field))
608			}
609			return nil
610		}
611		if err := check("reportId", r.ReportID); err != nil {
612			return err
613		}
614		if err := check("artifact.name", r.Artifact.Name); err != nil {
615			return err
616		}
617		if err := check("artifact.hash", r.Artifact.Hash); err != nil {
618			return err
619		}
620		ruleFields := []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
621		for i, rule := range r.Rules {
622			values := []string{rule.ID, rule.Kind, rule.Severity, rule.Invariant, rule.Version, rule.Status, rule.Note}
623			for j, value := range values {
624				if err := check(fmt.Sprintf("rules[%d].%s", i, ruleFields[j]), value); err != nil {
625					return err
626				}
627			}
628		}
629		findingFields := []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
630		for i, finding := range r.Findings {
631			values := []string{finding.ArtifactHash, finding.RuleID, finding.Version, finding.Severity, finding.Invariant, finding.Evidence}
632			for j, value := range values {
633				if err := check(fmt.Sprintf("findings[%d].%s", i, findingFields[j]), value); err != nil {
634					return err
635				}
636			}
637		}
638		return nil
639	}
