641	// duplicateArchiveError classifies an archive that repeats a JSON member as
642	// corrupt and names the requested report id, the decoded member name and the
643	// object carrying it (with array position and rule id when applicable).
644	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
645		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
646	}
