648	// characterArchiveError classifies an archive whose bytes are not legal JSON
649	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
650	// surrogate escape inside any member name or string value, including unknown
651	// extension members — as corrupt and names the requested report id together
652	// with the precise byte offset, line/column and JSON path. It is the
653	// read-side counterpart of the submission gate in ParseAuditInput: the decode
654	// below would otherwise replace both problems with U+FFFD and could accept a
655	// rewritten archive whose id and rule/finding evidence happened to match.
656	func characterArchiveError(id string, charErr *charEncodingError) error {
657		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
658	}
