660	// reportShape is the fixed-field shape of a stored report archive: the agreed
661	// spellings at the top level and inside the artifact, every rule and every
662	// finding. The trusted content of a report is carried by these fixed fields
663	// alone; case variants, whitespace-padded names and unknown members are
664	// extension data and never reach the decoder.
665	var reportShape = fixedShape{
666		keys: []string{"reportId", "artifact", "rules", "findings"},
667		objects: map[string]fixedShape{
668			"artifact": {keys: []string{"name", "hash"}},
669		},
670		arrays: map[string]fixedShape{
671			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
672			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
673		},
674	}
675	
676	// strictReportJSON rewrites archive bytes to the fixed report fields under
677	// their original spelling; see fixedShape for the recognition convention
678	// shared with the submission side.
679	func strictReportJSON(data []byte) ([]byte, error) {
680		return strictFixedJSON(data, reportShape)
681	}
