683	// validateArchiveRuleFields is the read-side counterpart of the submission
684	// gate in validateFormalRequiresABI. A ReportRule's typed members are Go
685	// bool/string fields, so decoding the strict archive straight into Report
686	// turns a formal null member into the zero value false or "": an archive that
687	// wrote "requiresABI":null, or "note":null on a passing rule without a note,
688	// would read byte-for-byte like one that omitted the member, the recomputed
689	// id and the rule/finding correspondence would all pass on that laundered
690	// value, and a diff could even compare the rule as unchanged. The shared
691	// checkRuleFieldTypes gate therefore inspects each written formal member's
692	// raw JSON token before that decoding happens. null or any other
693	// non-required type makes the whole archive corrupt, independently of the
694	// rule's check status and of whether it has a finding — the offending rule is
695	// never skipped and no partial report is returned. An omitted member still
696	// decodes to the zero value and an explicit empty string is still judged by
697	// the ordinary business rules: the string gate is about the JSON type alone,
698	// not about requiring text to be non-empty. The strict rewrite dropped
699	// extension members, so a case-variant or whitespace-padded name is invisible
700	// here: a correctly typed value it carries neither supplies nor rescues the
701	// formal value, and a null it carries never reaches this gate. locate renders
702	// the rule locator in the wording each gate historically used, and every
703	// error names the requested report id and is classified as archive
704	// corruption.
705	func validateArchiveRuleFields(strict []byte, id string, checks []ruleFieldTypeCheck,
706		locate func(int, map[string]json.RawMessage) string) error {
707		return checkRuleFieldTypes(strict, checks, ruleFieldTypeHooks{
708			locate: locate,
709			invalidJSON: func(err error) error {
710				return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
711			},
712			reject: func(where, field string, typ ruleFieldType) error {
713				return errCorrupt("report " + id + " archive is corrupt: " + where + ": " + field + " " + typ.requirement())
714			},
715		})
716	}
717	
718	// archiveRuleLocator names a rule in an archive error by its formal id
719	// ("rule r-bad"), falling back to "rule" when the id is missing, empty or not
720	// itself a legal string. It deliberately carries no rules-array position.
721	func archiveRuleLocator(_ int, rule map[string]json.RawMessage) string {
722		if ruleID := formalRuleID(rule); ruleID != "" {
723			return "rule " + ruleID
724		}
725		return "rule"
726	}
727	
728	// archiveRulePositionLocator names a rule's position in the rules array
729	// ("rules[1]") and, when the rule carries a legal non-empty id, also names it
730	// ("rules[1] (rule r-bad)").
731	func archiveRulePositionLocator(i int, rule map[string]json.RawMessage) string {
732		where := fmt.Sprintf("rules[%d]", i)
733		if ruleID := formalRuleID(rule); ruleID != "" {
734			where += " (rule " + ruleID + ")"
735		}
736		return where
737	}
