739	// validateArchiveRequiresABI runs the read-side boolean gate for the formal
740	// requiresABI member.
741	func validateArchiveRequiresABI(strict []byte, id string) error {
742		return validateArchiveRuleFields(strict, id,
743			[]ruleFieldTypeCheck{{field: "requiresABI", typ: ruleFieldBoolean}},
744			archiveRuleLocator)
745	}
