747	// archiveRuleTextFields lists the formal rule members whose value, once the
748	// member is written out, must be a JSON string.
749	var archiveRuleTextFields = []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
750	
751	// validateArchiveRuleText runs the read-side string gate for the text fields
752	// of every stored rule; see validateArchiveRuleFields for why the raw token is
753	// checked before decoding.
754	func validateArchiveRuleText(strict []byte, id string) error {
755		checks := make([]ruleFieldTypeCheck, len(archiveRuleTextFields))
756		for i, field := range archiveRuleTextFields {
757			checks[i] = ruleFieldTypeCheck{field: field, typ: ruleFieldString}
758		}
759		return validateArchiveRuleFields(strict, id, checks, archiveRulePositionLocator)
760	}
