762	// loadStoredReport parses archive bytes for id and fully validates them.
763	func loadStoredReport(data []byte, id string) (Report, error) {
764		// Read-side counterpart of the submission character gate in
765		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
766		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
767		// surrogate escape into U+FFFD, so an archive whose note and evidence both
768		// carried the substitution character could have those two spots changed to
769		// lone surrogate escapes and still decode to byte-identical content: the
770		// recomputed id and the rule/finding evidence comparison would then pass on
771		// the rewritten copy. Every raw string literal is checked first — member
772		// names and values, at every depth, inside unknown extension members too —
773		// and the whole archive is corrupt when any character is illegal, whatever
774		// id the rewritten content would compute.
775		if charErr := validateJSONCharacters(data); charErr != nil {
776			return Report{}, characterArchiveError(id, charErr)
777		}
778		// Read-side counterpart of the submission check: json.Unmarshal silently
779		// keeps the last value for a repeated member, so an archive that writes a
780		// rule status as 发现缺陷 and then 通过 would decode to whichever came
781		// last. The recomputed id and the rule/finding correspondence all operate
782		// on that last-wins value and could therefore pass, accepting an archive
783		// with two conflicting conclusions. Any repeated member in any object
784		// makes the archive corrupt, regardless of the last value.
785		if dup := findDuplicateJSONMember(data); dup != nil {
786			return Report{}, duplicateArchiveError(id, data, dup)
787		}
788		strict, err := strictReportJSON(data)
789		if err != nil {
790			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
791		}
792		// Check the formal requiresABI member against its raw JSON token before
793		// decoding into the Go bool below; otherwise a null value would silently
794		// become the zero value false and could pass every later check, including
795		// the content id, as if the archive had explicitly said false.
796		if err := validateArchiveRequiresABI(strict, id); err != nil {
797			return Report{}, err
798		}
799		// Same laundering hazard for the rule text fields: decoding into a Go
800		// string turns a formal null member into "", so an archive that wrote
801		// "note":null on a note-less passing rule would pass every later check,
802		// including the content id, as if the member had been omitted. Check the
803		// raw JSON token of every written formal text member before decoding.
804		if err := validateArchiveRuleText(strict, id); err != nil {
805			return Report{}, err
806		}
807		var r Report
808		if err := json.Unmarshal(strict, &r); err != nil {
809			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
810		}
811		if r.ReportID != id {
812			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
813		}
814		if err := validStoredReport(r); err != nil {
815			return Report{}, err
816		}
817		return r, nil
818	}
819	
820	// saveReportHook, when set, is invoked after the archive existence check and
821	// before the atomic publish. It lets tests simulate another process racing to
822	// claim the same report id.
823	var saveReportHook func(finalPath string)
824	
825	// SaveReport persists a report under the store directory. The store is safe
826	// for concurrent writers: identical reports share one file and all
827	// submissions succeed, different reports never overwrite each other, and
828	// readers only ever observe complete files. A submission is fully validated
829	// before any store operation, so an invalid report creates no store and no
830	// files. Every string in a directly constructed report must be valid UTF-8:
831	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
832	// content-addressed id matched the rewritten copy, reporting success for an
833	// archive whose text differs from the caller's; such a report is rejected as
834	// an input error before the store directory is touched. A pre-existing file
835	// with the same id must be a valid archive of the same report; a corrupted
836	// archive makes the submission fail while keeping the original file, even
837	// when the corruption appears only during the save. The first successfully
838	// archived bytes are never replaced by later submissions.
839	func SaveReport(dir string, r Report) error {
840		if err := validateSubmittedText(r); err != nil {
841			return err
842		}
843		if err := validSubmittedReport(r); err != nil {
844			return err
845		}
846		if err := os.MkdirAll(dir, 0o755); err != nil {
847			return err
848		}
849		finalPath := filepath.Join(dir, r.ReportID+".json")
850		if existing, err := os.ReadFile(finalPath); err == nil {
851			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
852				return err
853			}
854			return nil
855		} else if !os.IsNotExist(err) {
856			return err
857		}
858		data, err := json.Marshal(r)
859		if err != nil {
860			return err
861		}
862		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
863		if err != nil {
864			return err
865		}
866		tmpPath := tmp.Name()
867		cleanup := func() { os.Remove(tmpPath) }
868		if _, err := tmp.Write(data); err != nil {
869			tmp.Close()
870			cleanup()
871			return err
872		}
873		if err := tmp.Sync(); err != nil {
874			tmp.Close()
875			cleanup()
876			return err
877		}
878		if err := tmp.Close(); err != nil {
879			cleanup()
880			return err
881		}
882		if saveReportHook != nil {
883			saveReportHook(finalPath)
884		}
885		if err := os.Link(tmpPath, finalPath); err != nil {
886			cleanup()
887			if os.IsExist(err) {
888				existing, readErr := os.ReadFile(finalPath)
889				if readErr != nil {
890					return readErr
891				}
892				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
893					return err
894				}
895				return nil
896			}
897			return err
898		}
899		cleanup()
900		return nil
901	}
902	
903	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
904	// hex characters; missing, corrupted or tampered archives produce a clear
905	// error. The store is only read, never created or modified.
906	func LoadReport(dir, id string) (Report, error) {
907		if !validReportID(id) {
908			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
909		}
910		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
911		if err != nil {
912			if os.IsNotExist(err) {
913				return Report{}, errNotFound("report " + id + " not found")
914			}
915			return Report{}, err
916		}
917		return loadStoredReport(data, id)
918	}
919	
920	type errNotFound string
921	
922	func (e errNotFound) Error() string { return string(e) }
923	
924	type errCorrupt string
925	
926	func (e errCorrupt) Error() string { return string(e) }
927

