2	// audit submission and the stored report.
3	package contractsentinel
4	
5	import "encoding/json"
6	
7	// fixedShape describes the fixed fields of one JSON object: keys lists the
8	// agreed member spellings kept at this level, objects names members whose
9	// values are themselves objects with their own fixed shape, and arrays names
10	// members whose values are arrays of such objects. Members not named anywhere
11	// in the shape are extension data.
12	//
13	// Both entry points that decode user-supplied JSON — the audit submission and
14	// the stored report archive — are decoded through a fixedShape, so the
15	// recognition convention exists exactly once: a member denotes a fixed field
16	// only when its JSON-decoded name matches the agreed spelling byte for byte.
17	// encoding/json otherwise falls back to case-insensitive field matching, so
18	// an extension member such as "StAtus" would silently decode into the status
19	// field and could override — or launder — the conclusion carried by the
20	// formal "status" member, depending on where the extension member appears.
21	// Case variants, whitespace-padded names and unknown members never reach the
22	// decoder: they can neither override a formal value nor substitute for a
23	// missing, mistyped or unsupported one, whatever JSON type the extension
24	// value has. Names are compared after JSON string decoding, so a fixed name
25	// written with escapes still denotes that field.
26	type fixedShape struct {
27		keys    []string
28		objects map[string]fixedShape
29		arrays  map[string]fixedShape
30	}
31	
32	// strictFixedJSON rewrites data to the fixed fields of shape, at this level
33	// and inside every nested object member and every element of every nested
34	// array member named by the shape. Member order and extension members no
35	// longer influence the decoded values. Exact duplicate members were already
36	// rejected by findDuplicateJSONMember, so each kept name appears at most
37	// once. A null object member stays null so the decoded value keeps the same
38	// nil-ness as before.
39	func strictFixedJSON(data []byte, shape fixedShape) ([]byte, error) {
40		var obj map[string]json.RawMessage
41		if err := json.Unmarshal(data, &obj); err != nil {
42			return nil, err
43		}
44		out := make(map[string]json.RawMessage, len(shape.keys))
45		for _, k := range shape.keys {
46			if v, ok := obj[k]; ok {
47				out[k] = v
48			}
49		}
50		for name, sub := range shape.objects {
51			if raw, ok := out[name]; ok && string(raw) != "null" {
52				f, err := strictFixedJSON(raw, sub)
53				if err != nil {
54					return nil, err
55				}
56				out[name] = f
57			}
58		}
59		for name, sub := range shape.arrays {
60			if raw, ok := out[name]; ok {
61				f, err := strictFixedJSONArray(raw, sub)
62				if err != nil {
63					return nil, err
64				}
65				out[name] = f
66			}
67		}
68		return json.Marshal(out)
69	}
70	
71	// strictFixedJSONArray rewrites every element of a JSON array with
72	// strictFixedJSON. A null array stays null so the decoded slice keeps the
73	// same nil-ness as before.
74	func strictFixedJSONArray(raw json.RawMessage, shape fixedShape) (json.RawMessage, error) {
75		var elems []json.RawMessage
76		if err := json.Unmarshal(raw, &elems); err != nil {
77			return nil, err
78		}
79		if elems == nil {
80			return raw, nil
81		}
82		out := make([]json.RawMessage, 0, len(elems))
83		for _, e := range elems {
84			f, err := strictFixedJSON(e, shape)
85			if err != nil {
86				return nil, err
87			}
88			out = append(out, f)
89		}
90		return json.Marshal(out)
91	}
