10	// 本文件锁定 audit 提交侧的固定字段大小写规则，与 report 读取侧
11	// (report_strict_load_test.go) 保持一致：只有约定拼写的字段参与审计，
12	// StAtus、Version、RULES 这类大小写变体以及名称两侧带空格的成员都只是扩展
13	// 信息，出现在正式成员之前或之后、携带任意合法 JSON 类型都不能改写结论；
14	// 但扩展信息本身仍被允许，不能一遇未知名称就拒绝。不变式名称是用户定义的，
15	// Inv 与 inv 是两个独立不变式，名称空格也不修剪。字段名的 JSON 转义按解码
16	// 后的名称识别；重复成员（含扩展对象内部）仍整份拒绝。
17	
18	// strictTestArtifact 是本文件提交用例共享的产物，其 JSON 形态与字段值固定。
19	func strictTestArtifact() Artifact {
20		return Artifact{Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol"}
21	}
22	
23	const strictArtifactJSON = `{"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`
24	const strictRulesJSON = `[{"id":"r1","kind":"static","severity":"high","invariant":"inv","requiresABI":false,"version":"1.0.0"}]`
25	
26	// strictDoc 用顶层段落拼装一份提交，括号由本函数统一负责，避免手写时漏掉
27	// 外层大括号。
28	func strictDoc(sections ...string) string {
29		return "{" + strings.Join(sections, ",") + "}"
30	}
31	
32	// strictDefectCheck 是一条绑定正确产物哈希、正式结论为“发现缺陷”的检查
33	// 记录；formalPrefix 会被放在正式 status 之前（用于在正式字段前放扩展成员），
34	// formalSuffix 放在其后。
35	func strictDefectCheck(hash, formalPrefix, formalSuffix string) string {
36		return fmt.Sprintf(
37			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0",%s"status":"发现缺陷"%s,"note":"counterexample: x"}`,
38			hash, formalPrefix, formalSuffix)
39	}
40	
41	// strictParsedReport 解析并构建一份提交，返回报告；任一环节失败即终止。
42	func strictParsedReport(t *testing.T, in string) Report {
43		t.Helper()
44		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
45		if err != nil {
46			t.Fatalf("legal submission must parse: %v\ninput: %s", err, in)
47		}
48		report, err := BuildReport(artifact, rules, invariants, checks)
49		if err != nil {
50			t.Fatalf("legal submission must build a report: %v\ninput: %s", err, in)
51		}
52		return report
53	}
