362	// --- 不变式名称大小写敏感、空格不修剪；值仍只接受布尔 ---
363	
364	func TestParseAuditInvariantNamesAreUserDefined(t *testing.T) {
365		in := strictDoc(
366			`"artifact":`+strictArtifactJSON,
367			`"rules":`+strictRulesJSON,
368			`"invariants":{"Inv":true,"inv":false," inv ":true}`,
369		)
370		_, _, invariants, _, err := ParseAuditInput([]byte(in))
371		if err != nil {
372			t.Fatalf("Inv, inv and \" inv \" are three distinct invariants: %v", err)
373		}
374		if len(invariants) != 3 {
375			t.Fatalf("want 3 distinct invariant names, got %+v", invariants)
376		}
377		if invariants["Inv"] != true || invariants["inv"] != false || invariants[" inv "] != true {
378			t.Fatalf("invariant names/values not preserved exactly: %+v", invariants)
379		}
380	
381		// 规则引用小写 inv：取 false，产生缺陷，与 Inv / " inv " 无关。
382		got := strictParsedReport(t, in)
383		if len(got.Findings) != 1 || got.Findings[0].Invariant != "inv" {
384			t.Fatalf("rule must bind to lowercase inv=false: %+v", got.Findings)
385		}
386	
387		// 用户定义名称下，非布尔值依旧整体拒绝。
