453	// --- 已有报告时拒绝提交：不新增报告，也不改写已有内容 ---
454	
455	func TestCLIAuditImportChecksMismatchKeepsExistingReports(t *testing.T) {
456		bin := auditBinary(t)
457		work := t.TempDir()
458		store := filepath.Join(work, "reports")
459	
460		// 先落一份合法的混合状态报告。
461		good := writeStructInput(t, work, "good.json", mixedCheckInput(mixedArtifactHash(t)))
462		if _, stderr, code := runCLIAudit(t, bin, good, store); code != 0 {
463			t.Fatalf("valid setup audit must succeed: %s", stderr)
464		}
465		before, err := listFiles(store)
466		if err != nil {
467			t.Fatal(err)
468		}
469		if len(before) != 1 {
470			t.Fatalf("setup expected 1 report, got %v", before)
471		}
472		existingPath := filepath.Join(store, before[0])
473		existingBytes, err := os.ReadFile(existingPath)
474		if err != nil {
475			t.Fatal(err)
476		}
477	
478		// 再提交一份夹带哈希不匹配记录的提交。
479		badIn := mixedCheckInput(mixedArtifactHash(t))
480		badIn.Checks[2].ArtifactHash = strings.Repeat("b", 64)
481		bad := writeStructInput(t, work, "bad.json", badIn)
482		if _, _, code := runCLIAudit(t, bin, bad, store); code == 0 {
483			t.Fatal("invalid submission must exit non-zero")
484		}
485	
486		after, err := listFiles(store)
487		if err != nil {
488			t.Fatal(err)
489		}
490		if len(after) != len(before) || after[0] != before[0] {
491			t.Fatalf("rejected submission changed the store contents:\nbefore=%v\nafter=%v", before, after)
492		}
493		kept, err := os.ReadFile(existingPath)
494		if err != nil {
495			t.Fatal(err)
496		}
497		if !bytes.Equal(kept, existingBytes) {
498			t.Fatal("rejected submission modified the existing report bytes")
499		}
500	}
