// 失败时不得创建尚不存在的报告目录或任何归档。
func TestCLIAuditNullSourceCreatesNoStore(t *testing.T) {
	bin := auditBinary(t)
	work := t.TempDir()
	input := writeInput(t, work, "in.json", nullSourceInput)
	store := filepath.Join(work, "nested", "missing-store")

